#!/usr/bin/env bash
#
# A wizard — walks a human through steps only they can perform.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the terminal, then announce the step and show progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
REPOSITORY_ROOT=$(cd "$(dirname "$0")/../.." && pwd)
ACCEPTANCE_RECORD=${ACCEPTANCE_RECORD:-$REPOSITORY_ROOT/acceptance/slice-one-pstn.json}
ACCEPTANCE_CLI=$REPOSITORY_ROOT/apps/acceptance/src/cli.ts
RELEASE_COMMIT=$(git -C "$REPOSITORY_ROOT" rev-parse HEAD)

if [[ ! $RELEASE_COMMIT =~ ^[0-9a-f]{40}$ ]]; then
  warn "The repository HEAD is not a release commit."
  exit 1
fi
if [[ ! -f /opt/voice-agent/current/.voice-agent-release ]] || \
  [[ $(</opt/voice-agent/current/.voice-agent-release) != "$RELEASE_COMMIT" ]]; then
  warn "The checked-out commit is not the active immutable Agent Host Release."
  exit 1
fi
if [[ ! -f $ACCEPTANCE_RECORD ]]; then
  /usr/bin/env node --experimental-strip-types "$ACCEPTANCE_CLI" init \
    --record "$ACCEPTANCE_RECORD" \
    --campaign-id slice-one-production \
    --release-commit "$RELEASE_COMMIT"
elif [[ $(jq -r .releaseCommit "$ACCEPTANCE_RECORD") != "$RELEASE_COMMIT" ]]; then
  warn "The existing acceptance record belongs to a different release commit."
  exit 1
fi

record_run() {
  local carrier="$1" environment="$2" instructions="$3"
  local sequence callback_ms health_answer_ms interruption_count
  local callback_handshake bountywell_answer evidence_record completion_notice
  local manual_intervention boundaries result recorded_at
  sequence=$(($(jq '[.events[] | select(.kind == "pstn-run")] | length' "$ACCEPTANCE_RECORD") + 1))
  say "$instructions"
  step "Call the dedicated Voice Agent number from the named carrier, wait for the callback, answer as a human, and press DTMF 1."
  step "Ask naturally whether Bountywell is healthy. Request a completion notice only if this run is intended to exercise one."
  pause "Complete PSTN run $sequence, then press Enter to record it."
  ask TASK_URL "Authenticated Evidence Record task link:"
  ask CALLBACK_MS "Inbound ring to authorized callback latency in milliseconds:"
  ask HEALTH_ANSWER_MS "Final question to spoken health answer latency in milliseconds:"
  ask INTERRUPTION_COUNT "Number of natural response interruptions observed:"
  ask INTERRUPTION_OBSERVATION "Interruption observation (use 'None observed.' when zero):"
  ask TRANSCRIPTION_OBSERVATION "Qualitative transcription observation (do not paste a transcript):"
  ask COMPLETION_NOTICE "Completion notice outcome (sent, not-requested, or failed):"
  callback_handshake=failed
  bountywell_answer=incorrect
  evidence_record=incomplete
  manual_intervention=true
  boundaries=failed
  confirm "Did the complete Callback Handshake pass?" && callback_handshake=passed
  confirm "Did the Voice Agent correctly answer the Bountywell health question?" && bountywell_answer=correct
  confirm "Is the authenticated Evidence Record complete?" && evidence_record=complete
  if ! confirm "Did this run require any manual process, database, or service intervention after the inbound ring?"; then
    manual_intervention=false
  fi
  confirm "Did privacy, concurrency, spending, duration, and fail-closed boundaries remain satisfied?" && boundaries=passed
  callback_ms=$CALLBACK_MS
  health_answer_ms=$HEALTH_ANSWER_MS
  interruption_count=$INTERRUPTION_COUNT
  completion_notice=$COMPLETION_NOTICE
  if [[ ! $callback_ms =~ ^[0-9]+$ || ! $health_answer_ms =~ ^[0-9]+$ || \
    ! $interruption_count =~ ^[0-9]+$ || \
    ! $completion_notice =~ ^(sent|not-requested|failed)$ ]]; then
    warn "Latency/count fields must be non-negative integers and the notice outcome must be valid."
    exit 1
  fi
  result=failed
  if [[ $callback_handshake == passed && $bountywell_answer == correct && \
    $evidence_record == complete && $completion_notice != failed && \
    $manual_intervention == false && $boundaries == passed ]]; then
    result=passed
  fi
  recorded_at=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
  /usr/bin/env node --experimental-strip-types "$ACCEPTANCE_CLI" record-run \
    --record "$ACCEPTANCE_RECORD" \
    --sequence "$sequence" \
    --recorded-at "$recorded_at" \
    --carrier "$carrier" \
    --environment "$environment" \
    --result "$result" \
    --task-url "$TASK_URL" \
    --callback-ms "$callback_ms" \
    --health-answer-ms "$health_answer_ms" \
    --interruption-count "$interruption_count" \
    --interruption-observation "$INTERRUPTION_OBSERVATION" \
    --transcription-observation "$TRANSCRIPTION_OBSERVATION" \
    --callback-handshake "$callback_handshake" \
    --bountywell-answer "$bountywell_answer" \
    --evidence-record "$evidence_record" \
    --completion-notice "$completion_notice" \
    --manual-intervention "$manual_intervention" \
    --boundaries "$boundaries"
  if [[ $result == failed ]]; then
    warn "Run $sequence failed and remains in the record. It breaks the consecutive sequence."
  else
    note "Run $sequence passed and was appended to the record."
  fi
}

banner "Slice-one PSTN acceptance"

stage "Run automated release verification"
say "The acceptance event is recorded only after typechecking, the full test suite, deployment health, and the sanitized Prometheus scrape all pass for this exact commit."
if ! jq -e --arg commit "$RELEASE_COMMIT" \
  '.events[] | select(.kind == "automated-verification" and .commit == $commit)' \
  "$ACCEPTANCE_RECORD" >/dev/null; then
  corepack pnpm --dir "$REPOSITORY_ROOT" typecheck
  corepack pnpm --dir "$REPOSITORY_ROOT" test
  sudo /usr/local/libexec/voice-agent/deployment-health.sh
  curl --fail --silent --show-error --max-time 5 \
    http://127.0.0.1:3472/metrics | \
    grep -F 'voice_agent_monitoring_same_host 1' >/dev/null
  /usr/bin/env node --experimental-strip-types "$ACCEPTANCE_CLI" \
    record-verification \
    --record "$ACCEPTANCE_RECORD" \
    --recorded-at "$(date -u +%Y-%m-%dT%H:%M:%S.000Z)" \
    --release-commit "$RELEASE_COMMIT"
else
  note "Automated verification is already recorded for this release commit."
fi

stage "Inspect same-host operational telemetry"
say "In the existing Grafana interface, open Dashboards → Voice Agent → Voice Agent · Slice One Operational Path."
step "Confirm the Monitoring Boundary panel says Grafana and Prometheus share the Agent Host failure domain."
step "Confirm Voice Agent API/worker/broker and all five registered Bountywell probes are present; investigate any zero or stale series before continuing."
pause "Review the dashboard, then press Enter."

stage "PSTN run · AT&T indoor"
record_run att indoor "Use the owner's AT&T line in a quiet representative indoor setting."

stage "PSTN run · Tello indoor"
record_run tello indoor "Use the owner's Tello line in a quiet representative indoor setting."

stage "PSTN run · AT&T walking outdoors"
record_run att outdoor-walking "Use the owner's AT&T line while walking outdoors with representative telephone noise."

stage "PSTN run · Tello representative noise"
record_run tello indoor "Use the owner's Tello line with ordinary representative background noise."

stage "PSTN run · final consecutive attempt"
record_run att indoor "Use the owner's AT&T line for the fifth planned consecutive run."

stage "Validate and mark slice one accepted"
if ! /usr/bin/env node --experimental-strip-types "$ACCEPTANCE_CLI" status \
  --record "$ACCEPTANCE_RECORD"; then
  warn "The latest record is not ready. Failed runs remain preserved; rerun this wizard to append a new consecutive campaign."
  exit 1
fi
confirm "Accept slice one for this exact release commit?" || exit 1
/usr/bin/env node --experimental-strip-types "$ACCEPTANCE_CLI" accept \
  --record "$ACCEPTANCE_RECORD" \
  --recorded-at "$(date -u +%Y-%m-%dT%H:%M:%S.000Z)"
note "Slice one is accepted. Preserve and review $ACCEPTANCE_RECORD as release evidence."

finish
